class Solution {
    static java.util.Comparator<String> byLengthThenAlpha() {
        // TODO: 「だいたい同じ長さなら同値」は推移律を壊す。長さ -> 辞書順の順に比べる
        return (x, y) -> {
            if (Math.abs(x.length() - y.length()) <= 1) {
                return 0;
            }
            return x.length() - y.length();
        };
    }

    static java.util.List<String> sorted(java.util.List<String> xs) {
        java.util.List<String> copy = new java.util.ArrayList<>(xs);
        copy.sort(byLengthThenAlpha());
        return copy;
    }
}

answer_code:
class Solution {
    static java.util.Comparator<String> byLengthThenAlpha() {
        return java.util.Comparator.<String>comparingInt(String::length)
                .thenComparing(java.util.Comparator.<String>naturalOrder());
    }

    static java.util.List<String> sorted(java.util.List<String> xs) {
        java.util.List<String> copy = new java.util.ArrayList<>(xs);
        copy.sort(byLengthThenAlpha());
        return copy;
    }
}

