class Row {
    final String id;
    final String group;
    final int score;

    Row(String id, String group, int score) {
        this.id = id;
        this.group = group;
        this.score = score;
    }
}

class Solution {
    static java.util.List<String> arrange(java.util.List<Row> rows) {
        java.util.List<Row> work = new java.util.ArrayList<>(rows);
        work.sort((x, y) -> Integer.compare(y.score, x.score));
        work.sort((x, y) -> x.group.compareTo(y.group));
        java.util.List<String> ids = new java.util.ArrayList<>();
        for (Row r : work) {
            ids.add(r.id);
        }
        return ids;
    }
}

