class CountingSet<E> {
    private final java.util.Set<E> inner = new java.util.HashSet<>();
    private int addCount = 0;

    boolean add(E e) {
        addCount++;
        return inner.add(e);
    }

    boolean addAll(java.util.Collection<? extends E> c) {
        boolean changed = false;
        for (E e : c) {
            if (add(e)) {
                changed = true;
            }
        }
        return changed;
    }

    int addCount() {
        return addCount;
    }

    int size() {
        return inner.size();
    }

    boolean contains(Object o) {
        return inner.contains(o);
    }
}

