abstract class Pipeline {
    final int process(int[] xs) {
        int total = 0;
        for (int x : xs) {
            if (keep(x)) {
                total += transform(x);
            }
        }
        return total;
    }

    abstract boolean keep(int x);

    abstract int transform(int x);
}

class EvenDoubler extends Pipeline {
    @Override
    boolean keep(int x) {
        return x % 2 == 0;
    }

    @Override
    int transform(int x) {
        return x * 2;
    }
}

class OddSquares extends Pipeline {
    @Override
    boolean keep(int x) {
        return x % 2 != 0;
    }

    @Override
    int transform(int x) {
        return x * x;
    }
}

class Solution {
    static Pipeline evenDoubler() {
        return new EvenDoubler();
    }

    static Pipeline oddSquares() {
        return new OddSquares();
    }
}

