class Solution {
    private static final java.util.Map<String, java.util.function.IntBinaryOperator> STRATEGIES =
            new java.util.HashMap<>();

    static {
        STRATEGIES.put("add", (a, b) -> a + b);
        STRATEGIES.put("mul", (a, b) -> a * b);
        STRATEGIES.put("max", Math::max);
        STRATEGIES.put("min", Math::min);
    }

    static java.util.Map<String, java.util.function.IntBinaryOperator> strategies() {
        return STRATEGIES;
    }

    static int run(String name, int a, int b) {
        java.util.function.IntBinaryOperator op = STRATEGIES.get(name);
        if (op == null) {
            throw new IllegalArgumentException("unknown strategy: " + name);
        }
        return op.applyAsInt(a, b);
    }
}

