import java.util.List;

class Solution {
    static void swapEnds(List<?> list) {
        swapEndsCaptured(list);
    }

    // ワイルドカードに T という名前を与えるためのヘルパー
    private static <T> void swapEndsCaptured(List<T> list) {
        if (list.size() < 2) {
            return;
        }
        int last = list.size() - 1;
        T first = list.get(0);
        list.set(0, list.get(last));
        list.set(last, first);
    }
}

