import java.util.List;

sealed interface Json permits JNull, JNum, JArr {}

record JNull() implements Json {}

record JNum(int value) implements Json {}

record JArr(List<Json> items) implements Json {}

class Solution {
    static String render(Json json) {
        return switch (json) {
            case JNull ignored -> "null";
            case JNum(var value) -> String.valueOf(value);
            case JArr(var items) -> {
                StringBuilder sb = new StringBuilder("[");
                for (int i = 0; i < items.size(); i++) {
                    if (i > 0) {
                        sb.append(",");
                    }
                    sb.append(render(items.get(i)));
                }
                yield sb.append("]").toString();
            }
        };
    }

    // 新しい操作を足しても、型定義側は 1 行も触らずに済む
    static int depth(Json json) {
        return switch (json) {
            case JNull ignored -> 1;
            case JNum ignored -> 1;
            case JArr(var items) -> {
                int deepest = 0;
                for (Json item : items) {
                    deepest = Math.max(deepest, depth(item));
                }
                yield 1 + deepest;
            }
        };
    }
}

