import java.util.stream.Collector;

record Stats(int count, int sum, int min, int max) {}

// 集計途中の可変コンテナ
class StatsAcc {
    int count = 0;
    int sum = 0;
    int min = Integer.MAX_VALUE;
    int max = Integer.MIN_VALUE;
}

class Solution {
    static Collector<Integer, ?, Stats> toStats() {
        return Collector.of(
                StatsAcc::new,
                (StatsAcc acc, Integer n) -> {
                    acc.count++;
                    acc.sum += n;
                    acc.min = Math.min(acc.min, n);
                    acc.max = Math.max(acc.max, n);
                },
                (StatsAcc a, StatsAcc b) -> {
                    a.count += b.count;
                    a.sum += b.sum;
                    a.min = Math.min(a.min, b.min);
                    a.max = Math.max(a.max, b.max);
                    return a;
                },
                (StatsAcc acc) -> acc.count == 0
                        ? new Stats(0, 0, 0, 0)
                        : new Stats(acc.count, acc.sum, acc.min, acc.max));
    }
}

