import java.util.TreeSet;
import java.util.stream.Collector;

class Solution {
    static Collector<String, ?, TreeSet<String>> toSortedSet() {
        // finisher を渡さない形にすると IDENTITY_FINISH が自動で付く。
        // 結果は TreeSet なので、要素の到着順は結果に影響しない = UNORDERED。
        return Collector.of(
                TreeSet<String>::new,
                TreeSet::add,
                (TreeSet<String> a, TreeSet<String> b) -> {
                    a.addAll(b);
                    return a;
                },
                Collector.Characteristics.UNORDERED);
    }
}

