import java.util.Spliterator;
import java.util.function.Consumer;
import java.util.stream.Stream;
import java.util.stream.StreamSupport;

class IntArraySpliterator implements Spliterator<Integer> {
    private final int[] data;
    private int cur;
    private final int end;

    IntArraySpliterator(int[] data, int start, int end) {
        this.data = data;
        this.cur = start;
        this.end = end;
    }

    @Override
    public boolean tryAdvance(Consumer<? super Integer> action) {
        if (cur >= end) {
            return false;
        }
        action.accept(data[cur++]);
        return true;
    }

    @Override
    public Spliterator<Integer> trySplit() {
        int remaining = end - cur;
        if (remaining < 2) {
            return null;
        }
        int mid = cur + remaining / 2;
        Spliterator<Integer> prefix = new IntArraySpliterator(data, cur, mid);
        cur = mid;
        return prefix;
    }

    @Override
    public long estimateSize() {
        return end - cur;
    }

    @Override
    public int characteristics() {
        return ORDERED | SIZED | SUBSIZED | NONNULL | IMMUTABLE;
    }
}

class Solution {
    static Spliterator<Integer> spliteratorOf(int[] data) {
        return new IntArraySpliterator(data, 0, data.length);
    }

    static Stream<Integer> stream(int[] data, boolean parallel) {
        return StreamSupport.stream(spliteratorOf(data), parallel);
    }
}

