import java.util.List;

class Solution {
    static int totalLength(List<String> words) {
        // identity は 0 (0 + x == x)。combiner は部分和の足し算
        return words.parallelStream().reduce(0, (acc, w) -> acc + w.length(), Integer::sum);
    }

    static String longest(List<String> words) {
        // identity は ""。演算は「長いほう、同点なら左」= 結合則を満たす
        return words.parallelStream().reduce("", (a, b) -> a.length() >= b.length() ? a : b);
    }
}

