import java.util.List;
import java.util.stream.Stream;

class Solution {
    /** 並列化して得になる下限 (ナノ秒)。 */
    static final long THRESHOLD_NANOS = 100_000L;

    static boolean shouldParallelize(int size, boolean splittable, long perElementNanos) {
        if (!splittable || size <= 0 || perElementNanos <= 0) {
            return false;
        }
        return (long) size * perElementNanos >= THRESHOLD_NANOS;
    }

    static long sumOfSquares(List<Integer> xs) {
        if (xs.isEmpty()) {
            return 0L;
        }
        // 1 要素あたり 50ns 程度の軽い計算だと見積もる
        Stream<Integer> s = shouldParallelize(xs.size(), true, 50L)
                ? xs.parallelStream()
                : xs.stream();
        return s.mapToLong(x -> (long) x * x).sum();
    }
}

