import java.util.ArrayList;
import java.util.List;
import java.util.Optional;

class Solution {
    static List<Integer> doubledInOrder(List<Integer> src) {
        List<Integer> out = new ArrayList<>();
        // forEachOrdered は出現順に、しかも 1 スレッドずつ呼ばれることが保証される
        src.parallelStream().map(x -> x * 2).forEachOrdered(out::add);
        return out;
    }

    static Optional<Integer> firstAtLeast(List<Integer> src, int min) {
        return src.parallelStream().filter(x -> x >= min).findFirst();
    }
}

