        int nl = text.indexOf('\n');
        return (nl < 0) ? text : text.substring(0, nl);
    }

    static String lastChars(String s, int n) {
        if (n <= 0) {
            return "";
        }
        if (n >= s.length()) {
            return s;
        }
        return s.substring(s.length() - n);
    }
}

