import java.util.HashMap;
import java.util.List;
import java.util.Map;

class Solution {
    static final int MAX_CAPACITY = 1 << 30;

    static int capacityFor(int expectedSize) {
        if (expectedSize < 0) {
            throw new IllegalArgumentException("expectedSize must be >= 0: " + expectedSize);
        }
        int cap = 1;
        // cap * 0.75 < expectedSize を、小数を使わずに cap * 3 < expectedSize * 4 で判定する
        while (cap < MAX_CAPACITY && (long) cap * 3 < (long) expectedSize * 4) {
            cap <<= 1;
        }
        return cap;
    }

    static Map<String, Integer> presized(List<String> keys) {
        Map<String, Integer> map = new HashMap<>(capacityFor(keys.size()));
        for (int i = 0; i < keys.size(); i++) {
            map.put(keys.get(i), i);
        }
        return map;
    }
}

