    /** HashMap と同じ攪拌 + マスクでバケットを決め、最も混んだバケットの件数を返す。 */
    static int maxBucketLoad(List<Cell> cells, int buckets) {
        int[] load = new int[buckets];
        for (Cell c : cells) {
            int h = c.hashCode();
            h ^= (h >>> 16);
            load[Math.floorMod(h, buckets)]++;
        }
        int max = 0;
        for (int n : load) {
            max = Math.max(max, n);
        }
        return max;
    }
}

