import java.util.HashMap;
import java.util.Map;
import java.util.WeakHashMap;

class Solution {
    static Map<Object, String> newCache() {
        // TODO: キーが到達不能になったらエントリごと消えるマップを返す
        return new HashMap<>();
    }

    /** GC を促しながら、サイズが expected 以下になるのを待つ。最終的なサイズを返す。 */
    static int waitForShrink(Map<Object, String> cache, int expected, int attempts) {
        for (int i = 0; i < attempts && cache.size() > expected; i++) {
            System.gc();
            byte[] pressure = new byte[1 << 20]; // 割り当て圧をかける
            if (pressure.length < 0) {
                System.out.print("");
            }
            try {
                Thread.sleep(5);
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
                break;
            }
        }
        return cache.size();
    }
}

