import java.util.IdentityHashMap;
import java.util.List;
import java.util.Map;

class Solution {
    static int countDistinctInstances(List<Object> objects) {
        // IdentityHashMap は == と System.identityHashCode で判定する
        Map<Object, Boolean> seen = new IdentityHashMap<>();
        for (Object o : objects) {
            seen.put(o, Boolean.TRUE);
        }
        return seen.size();
    }

    static boolean containsSameInstance(List<Object> pool, Object target) {
        for (Object o : pool) {
            if (o == target) {
                return true;
            }
        }
        return false;
    }
}

