import java.util.concurrent.atomic.AtomicInteger;

class Solution {
    static int updateMax(AtomicInteger ref, int candidate) {
        while (true) {
            int current = ref.get();
            if (candidate <= current) {
                return current; // 更新不要
            }
            if (ref.compareAndSet(current, candidate)) {
                return candidate;
            }
            // 誰かに先を越された。読み直してやり直す
        }
    }

    static int addAndGetViaCas(AtomicInteger ref, int delta) {
        while (true) {
            int current = ref.get();
            int next = current + delta;
            if (ref.compareAndSet(current, next)) {
                return next;
            }
        }
    }
}

