            });
        }
        for (Thread t : ts) { t.start(); }
        for (Thread t : ts) { t.join(); }
        check(shared.total() == 160000L, "no_lost_updates_under_contention");

        shared.add(-160000L);
        check(shared.total() == 0L, "add_after_contention");

        Solution.HitCounter fresh = new Solution.HitCounter();
        fresh.add(5);
        check(fresh.total() == 5L && shared.total() == 0L, "instances_independent");
        if (failed > 0) { System.out.println("test result: FAILED"); System.exit(1); }
        System.out.println("test result: ok");
    }
}

