import java.util.concurrent.atomic.LongAdder;

class Solution {
    static final class HitCounter {
        // 内部で複数のセルに分散して加算するため、書き込みの競合が減る
        private final LongAdder adder = new LongAdder();

        void hit() {
            adder.increment();
        }

        void add(long delta) {
            adder.add(delta);
        }

        long total() {
            return adder.sum();
        }

        void reset() {
            adder.reset();
        }
    }
}

