import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.ConcurrentHashMap;

class Solution {
    static void addCount(ConcurrentHashMap<String, Integer> map, String key, int delta) {
        // 不在なら delta、あれば Integer::sum を適用。どちらも区画ロック下で行われる
        map.merge(key, delta, Integer::sum);
    }

    static List<String> appendTag(ConcurrentHashMap<String, List<String>> map, String key, String tag) {
        return map.compute(key, (k, current) -> {
            List<String> next = (current == null) ? new ArrayList<>() : new ArrayList<>(current);
            next.add(tag);
            return next; // 毎回新しいリストに差し替えるので、外に漏れた参照が壊れない
        });
    }
}

