import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.ArrayBlockingQueue;
import java.util.concurrent.BlockingQueue;

class Solution {
    static List<Integer> transfer(List<Integer> input, int capacity) throws InterruptedException {
        final BlockingQueue<Integer> queue = new ArrayBlockingQueue<>(Math.max(1, capacity));
        Thread producer = new Thread(() -> {
            try {
                for (Integer value : input) {
                    queue.put(value);
                }
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
        });
        producer.setDaemon(true);
        producer.start();

        List<Integer> received = new ArrayList<>(input.size());
        for (int i = 0; i < input.size(); i++) {
            received.add(queue.take());
        }
        producer.join();
        return received;
    }
}

