import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.Callable;
import java.util.concurrent.ExecutionException;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.Future;

class Solution {
    /** 1 件 50ms かかる重い処理 (擬似)。 */
    static int weigh(String word) throws InterruptedException {
        Thread.sleep(50);
        return word.length();
    }

    static List<Integer> weighAll(List<String> words) throws InterruptedException {
        if (words.isEmpty()) {
            return new ArrayList<>();
        }
        ExecutorService pool = Executors.newFixedThreadPool(Math.min(words.size(), 16));
        try {
            List<Callable<Integer>> tasks = new ArrayList<>();
            for (final String word : words) {
                tasks.add(() -> weigh(word));
            }
            List<Integer> results = new ArrayList<>(words.size());
            for (Future<Integer> future : pool.invokeAll(tasks)) {
                try {
                    results.add(future.get());
                } catch (ExecutionException e) {
                    throw new RuntimeException(e.getCause());
                }
            }
            return results;
        } finally {
            pool.shutdown();
        }
    }
}

