import java.util.Map;
import java.util.concurrent.CompletableFuture;

class Solution {
    private static final Map<Integer, String> NAMES = Map.of(1, "alice", 2, "bob");
    private static final Map<String, Integer> SCORES = Map.of("alice", 5, "bob", 3);

    /** 与えられたもの: id から名前を非同期に引く。 */
    static CompletableFuture<String> nameOf(int id) {
        return CompletableFuture.supplyAsync(() -> NAMES.getOrDefault(id, "unknown"));
    }

    /** 与えられたもの: 名前からスコアを非同期に引く。 */
    static CompletableFuture<Integer> scoreOf(String name) {
        return CompletableFuture.supplyAsync(() -> SCORES.getOrDefault(name, 0));
    }

    static CompletableFuture<String> report(int id) {
        return nameOf(id)
            .thenCompose(name -> scoreOf(name).thenApply(score -> name + ":" + score));
    }
}

