    static int fetch(String url) throws InterruptedException {
        Thread.sleep(60);
        return url.length();
    }

    static int fetchAll(List<String> urls) throws InterruptedException {
        // TODO: 待ち時間ばかりなのに、同時実行数がスレッド数で頭打ちになっている
        ExecutorService pool = Executors.newFixedThreadPool(2);
        try {
            List<Future<Integer>> futures = new ArrayList<>();
            for (final String url : urls) {
                futures.add(pool.submit(() -> fetch(url)));
            }
            int total = 0;
            for (Future<Integer> future : futures) {
                total += future.get();
            }
            return total;
        } catch (ExecutionException e) {
            throw new RuntimeException(e.getCause());
        } finally {
            pool.shutdown();
        }
    }
}

