import java.util.concurrent.ForkJoinPool;
import java.util.concurrent.RecursiveTask;

class Solution {
    static long parallelSum(int[] data, int threshold) {
        if (data.length == 0) {
            return 0L;
        }
        int limit = Math.max(1, threshold);
        return ForkJoinPool.commonPool().invoke(new SumTask(data, 0, data.length, limit));
    }

    static class SumTask extends RecursiveTask<Long> {
        private final int[] data;
        private final int from;
        private final int to;
        private final int threshold;

        SumTask(int[] data, int from, int to, int threshold) {
            this.data = data;
            this.from = from;
            this.to = to;
            this.threshold = threshold;
        }

        @Override
        protected Long compute() {
            if (to - from <= threshold) {
                long sum = 0L;
                for (int i = from; i < to; i++) {
                    sum += data[i];
                }
                return sum;
            }
            int mid = from + (to - from) / 2;
            SumTask left = new SumTask(data, from, mid, threshold);
            left.fork();
            SumTask right = new SumTask(data, mid, to, threshold);
            long rightSum = right.compute();
            return left.join() + rightSum;
        }
    }
}

