class Solution {
    static boolean nearlyEquals(double a, double b, double epsilon) {
        if (a == b) {
            return true; // 完全一致と無限大どうしはここで確定する
        }
        double diff = Math.abs(a - b);
        double scale = Math.max(Math.abs(a), Math.abs(b));
        if (scale < 1.0) {
            return diff <= epsilon;          // 0 付近は絶対誤差
        }
        return diff <= epsilon * scale;      // 大きい値は相対誤差
    }
}

