class Solution {
    static int wrapIndex(int i, int size) {
        int r = i % size;          // -3..3 の範囲で符号は i に従う
        return r < 0 ? r + size : r;
    }

    static int bucketOf(int value, int width) {
        int q = value / width;     // 0 方向への切り捨て
        if (value % width != 0 && (value < 0) != (width < 0)) {
            q--;                   // 商が負で割り切れないときだけ 1 つ下げる
        }
        return q;
    }
}

