import java.util.ConcurrentModificationException;
import java.util.Iterator;
import java.util.NoSuchElementException;

class Solution implements Iterable<Integer> {
    private final int[] buf;
    private int head;      // 最古の要素の位置
    private int size;
    private int modCount;  // 構造変更の回数

    Solution(int capacity) {
        if (capacity <= 0) throw new IllegalArgumentException("capacity");
        this.buf = new int[capacity];
    }

    int size() { return size; }

    void add(int v) {
        if (size == buf.length) {
            buf[head] = v;
            head = (head + 1) % buf.length;
        } else {
            buf[(head + size) % buf.length] = v;
            size++;
        }
        modCount++;
    }

    public Iterator<Integer> iterator() {
        return new Iterator<Integer>() {
            private int i = 0;
            private final int expected = modCount;   // 生成時点のスナップショット

            private void checkForComodification() {
                if (modCount != expected) throw new ConcurrentModificationException();
            }

            public boolean hasNext() {
                checkForComodification();
                return i < size;
            }

            public Integer next() {
                checkForComodification();
                if (i >= size) throw new NoSuchElementException();
                return buf[(head + i++) % buf.length];
            }
        };
    }
}

