import java.util.List;
import java.util.OptionalInt;

class Solution {
    static int throwCount = 0;

    /** 既存の厳格な API (変更しないこと)。 */
    static int strictParse(String s) {
        try {
            return Integer.parseInt(s);
        } catch (NumberFormatException e) {
            throwCount++;
            throw e;
        }
    }

    static OptionalInt tryParse(String s) {
        if (s == null || s.isEmpty()) return OptionalInt.empty();

        int i = 0;
        boolean negative = false;
        char first = s.charAt(0);
        if (first == '-' || first == '+') {
            negative = (first == '-');
            i = 1;
            if (s.length() == 1) return OptionalInt.empty();
        }

        long acc = 0;
        for (; i < s.length(); i++) {
            char c = s.charAt(i);
            if (c < '0' || c > '9') return OptionalInt.empty();
            acc = acc * 10 + (c - '0');
            if (acc > 2147483648L) return OptionalInt.empty();   // これ以上は int に収まらない
        }

        long value = negative ? -acc : acc;
        if (value < Integer.MIN_VALUE || value > Integer.MAX_VALUE) return OptionalInt.empty();
        return OptionalInt.of((int) value);
    }

    static long sumValid(List<String> inputs) {
        long total = 0;
        for (String s : inputs) {
            OptionalInt v = tryParse(s);
            if (v.isPresent()) total += v.getAsInt();
        }
        return total;
    }
}

