import java.lang.ref.Cleaner;

class Solution implements AutoCloseable {
    private static final Cleaner CLEANER = Cleaner.create();

    static int cleanedCount = 0;

    /** 後始末に必要な状態だけを持つ。static なので Solution を参照しない。 */
    static class State implements Runnable {
        private final String name;
        State(String name) { this.name = name; }
        @Override public void run() { cleanedCount++; }
    }

    private final Cleaner.Cleanable cleanable;

    Solution(String name) {
        this.cleanable = CLEANER.register(this, new State(name));
    }

    @Override
    public void close() {
        cleanable.clean();   // 高々 1 回しか実行されない
    }
}

