import java.lang.reflect.Field;
import java.lang.reflect.Method;

class Box {
    private final int value;
    Box(int value) { this.value = value; }
    private int doubled() { return value * 2; }
    String label() { return "box(" + value + ")"; }
}

class Solution {
    static int readValue(Object target) throws Exception {
        Field f = target.getClass().getDeclaredField("value");
        f.setAccessible(true);          // private の壁を外す
        return f.getInt(target);
    }

    static Object invokeNoArg(Object target, String name) throws Exception {
        Method m = target.getClass().getDeclaredMethod(name);
        m.setAccessible(true);
        return m.invoke(target);        // 戻り値は Object (int は Integer にボクシングされる)
    }
}

