import java.lang.reflect.InvocationHandler;
import java.lang.reflect.Method;
import java.lang.reflect.Proxy;
import java.util.ArrayList;
import java.util.List;

interface Greeter {
    String greet(String name);
    int count();
}

class SimpleGreeter implements Greeter {
    private int calls = 0;
    public String greet(String name) { calls++; return "こんにちは、" + name; }
    public int count() { return calls; }
}

class Solution {
    static final List<String> LOG = new ArrayList<>();

    static Greeter logging(Greeter target) {
        InvocationHandler handler = (proxy, method, args) -> {
            LOG.add(method.getName() + "/" + (args == null ? 0 : args.length));
            return method.invoke(target, args);
        };
        return (Greeter) Proxy.newProxyInstance(
            Greeter.class.getClassLoader(),
            new Class<?>[] { Greeter.class },
            handler);
    }
}

