import java.lang.annotation.ElementType;
import java.lang.annotation.Retention;
import java.lang.annotation.RetentionPolicy;
import java.lang.annotation.Target;
import java.lang.reflect.Method;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;

@Retention(RetentionPolicy.RUNTIME)
@Target(ElementType.METHOD)
@interface Label {
    String value();
    int order() default 0;
}

class Report {
    @Label(value = "名前", order = 1) String name() { return "太郎"; }
    @Label(value = "年齢", order = 2) String age() { return "20"; }
    String internalId() { return "x-1"; }
}

class Plain {
    String a() { return ""; }
}

class Solution {
    static List<String> labelsOf(Class<?> type) {
        List<Method> annotated = new ArrayList<>();
        for (Method m : type.getDeclaredMethods()) {
            if (m.getAnnotation(Label.class) != null) annotated.add(m);
        }
        // getDeclaredMethods の順序は未定義なので、必ず自分で並べ替える
        annotated.sort(Comparator.comparingInt(m -> m.getAnnotation(Label.class).order()));

        List<String> labels = new ArrayList<>();
        for (Method m : annotated) {
            labels.add(m.getAnnotation(Label.class).value());
        }
        return labels;
    }
}

