import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Optional;

class Solution {
    private static final Map<String, List<String>> DATA = new HashMap<>();
    static {
        DATA.put("fruit", List.of("りんご", "みかん"));
        DATA.put("veg", List.of("にんじん"));
    }

    static List<String> findAll(String key) {
        return DATA.getOrDefault(key, List.of());   // List.of() は不変な空リスト
    }

    static Optional<String> findOne(String key) {
        List<String> found = findAll(key);
        return found.isEmpty() ? Optional.empty() : Optional.of(found.get(0));
    }

    static String summary(String key) {
        List<String> found = findAll(key);
        return found.isEmpty() ? "該当なし" : String.join("・", found);
    }
}

