import java.util.List;
import java.util.Locale;

interface Formatter {
    String format(String s);

    default String formatAll(List<String> items) {
        StringBuilder sb = new StringBuilder();
        for (String s : items) {
            if (sb.length() > 0) sb.append(", ");
            sb.append(format(s));
        }
        return sb.toString();
    }

    default Formatter andThen(Formatter next) {
        // 抽象メソッドが 1 つだけなのでラムダで書ける
        return s -> next.format(this.format(s));
    }
}

class Upper implements Formatter {
    public String format(String s) { return s.toUpperCase(Locale.ROOT); }
}

class Bracket implements Formatter {
    public String format(String s) { return "[" + s + "]"; }

    @Override
    public String formatAll(List<String> items) {
        StringBuilder sb = new StringBuilder();
        for (String s : items) sb.append(format(s));
        return sb.toString();
    }
}

class Solution {
    static Formatter upper() { return new Upper(); }
    static Formatter bracket() { return new Bracket(); }
}
